import * as B from './bucket';
import {assign, define, isOwn, parseString, PDESC, toLowAscii} from './util';

/**
 * @property {{col: number, line: number, offset: number}} end
 * @property {[]} [args] added in selectors
 * @property {string} [atName] lowercase name of @-rule without -vendor- prefix
 * @property {TokenValue} [expr] body of function or block
 * @property {'*'|'_'} [hack] for property name in IE mode
 * @property {string} [lowText] text.toLowerCase() added on demand
 * @property {string} [name] name of function
 * @property {number} [number] parsed number
 * @property {string} [prefix] lowercase `-vendor-` prefix
 * @property {string} [units] lowercase units of a number
 * @property {string} [uri] parsed uri string
 * @property {number} [vendor] low 16bit: char code of vendor name i.e. 102 for "f" in -moz-foo,
 * high 16bit: position of vendor name i.e. 5 for "f" in -moz-foo
 */
export default class Token {
  constructor(id, col, line, offset, input, code) {
    /** @type {number} */
    this.id = id;
    this.is = 0;
    this.col = col;
    this.line = line;
    this.offset = offset;
    this.lowText = null;
    this.type = '';
    this.code = toLowAscii(code);
    this._input = input;
  }

  /** @return {Token} */
  static from(tok) {
    return assign(Object.create(this.prototype), tok);
  }

  get length() {
    return isOwn(this, 'text') ? this.text.length : this.end.offset - this.offset;
  }

  get string() {
    const str = PDESC.value = parseString(this.text);
    define(this, 'string', PDESC);
    return str;
  }

  set string(val) {
    PDESC.value = val;
    define(this, 'string', PDESC);
  }

  get text() {
    return this._input.slice(this.offset, this.end.offset);
  }

  set text(val) {
    PDESC.value = val;
    define(this, 'text', PDESC);
  }

  valueOf() {
    return this.text;
  }

  toString() {
    return this.text;
  }
}

export class TokenFunc extends Token {
  /**
   * @param {Token} tok
   * @param {TokenValue} [expr]
   * @param {Token} [end]
   * @return {Token}
   */
  static from(tok, expr, end) {
    tok = super.from(tok);
    if (isOwn(tok, 'text'))
      tok.offsetBody = tok.end.offset;
    if (end)
      tok.end = end.end;
    if (expr) {
      tok.expr = expr;
      let n = tok.name;
      n = B.calc.has(tok, n) ? IS_CALC
        : n === 'var' || n === 'env' || tok.id === DASHED_FUNCTION ? IS_VAR
        : n === 'attr' && (n = expr.parts[0]) && (n.id === IDENT || n.id === UVAR) ? IS_ATTR
        : 0;
      if (n) tok.is = n;
    }
    return tok;
  }

  toString() { // FIXME: account for escapes
    const s = this._input;
    return isOwn(this, 'text')
      ? this.text + s.slice(this.offsetBody + 1, this.end.offset)
      : s.slice(this.offset, this.end.offset);
  }
}

/**
 * @template T
 * @prop {(T | Token)[]} parts
 */
export class TokenValue extends Token {
  /** @return {TokenValue} */
  static from(parts, tok = parts[0]) {
    tok = super.from(tok);
    tok.parts = parts;
    return tok;
  }

  /** @return {TokenValue} */
  static empty(tok) {
    tok = super.from(tok);
    tok.parts = [];
    tok.id = WS;
    tok.end = {col: tok.col, line: tok.line, offset: tok.offset};
    delete tok.text;
    return tok;
  }

  get text() { // FIXME: account for escapes
    return this._input.slice(this.offset, (this.parts[this.parts.length - 1] || this).end.offset);
  }

  set text(val) {
    PDESC.value = val;
    define(this, 'text', PDESC);
  }
}
